def test_case(pred_sqls, sol_sqls, db_name, conn):
        after_query = """
            SELECT COUNT(*) AS count
            FROM auditandcompliance ac WHERE (ac.critfindnum::numeric / (ac.findtally + 1)) > 0.5
            AND ac.remeddue < CURRENT_DATE AND ac.remedstate NOT IN ('Complete', 'Overdue');
        """

        res = execute_queries([after_query], 'cross_db',conn)[0]

        if res[0][0] == 0:
            return True
        else:
            raise AssertionError(f"Found {after_query[0][0]} records that should have been updated but weren't")
